126:             int numColumns)
127:         {
128:             List<AKRSPoint2D> pointList = new List<AKRSPoint2D>();
129: 
130:             double startX = centerPoint.X - ((numColumns - 1) / 2.0 * distanceX); // 左上角点的X坐标
131:             double startY = centerPoint.Y - ((numRows - 1) / 2.0 * distanceY); // 左上角点的Y坐标
132: 
133:             for (int i = 0; i < numRows; i++)
134:             {
135:                 for (int j = 0; j < numColumns; j++)
