87:         public static List<AKRSPoint2D> GeneratePointList(
88:             AKRSPoint3D centerPoint,
89:             double distance,
90:             int numRows,
91:             int numColumns)
92:         {
93:             List<AKRSPoint2D> pointList = new List<AKRSPoint2D>();
94: 
95:             double startX = centerPoint.X - ((numColumns - 1) / 2.0 * distance); // 左上角点的X坐标
96:             double startY = centerPoint.Y - ((numRows - 1) / 2.0 * distance); // 左上角点的Y坐标
97: 
98:             for (int i = 0; i < numRows; i++)
99:             {
100:                 for (int j = 0; j < numColumns; j++)
101:                 {
102:                     double x = startX + (j * distance);
103:                     double y = startY + (i * distance);
104:                     AKRSPoint2D point = new AKRSPoint2D(x, y);
105:                     pointList.Add(point);
106:                 }
107:             }
108: 
109:             return pointList;
110:         }
