184:                 out HTuple hv_Radius,
185:                 out HTuple hv_StartPhi,
186:                 out HTuple hv_EndPhi,
187:                 out HTuple hv_PointOrder);
188: 
189:             centerX = hv_Col.D;
190:             centerY = hv_Row.D;
191:             radius = hv_Radius.D;
192: 
193:             circleContour.Dispose();
194:         }

