161:         public bool LocateAndMoveToTargetPixel(string prName, CamCoordinateType camType, double pixelTolerance, int maxRetry)
162:         {
163:             int retryCount = 0;
164:             MatchResult currentMatchResult = null;
165:             bool isWithinTolerance = false;
166: 
167:             // 目标像素点（固定为1224,1024）
168:             (double targetX, double targetY) = (1224, 1024);
169: 
170:             // 记录最终偏差（用于日志）
171:             (double finalDeltaX, double finalDeltaY) = (0, 0);
172: 
173:             while (retryCount < maxRetry)
174:             {
175:                 // 1. 首次定位并移动
176:                 currentMatchResult = LocateAndMoveOnce(prName, camType);
177:                 if (currentMatchResult == null || !currentMatchResult.IsSuccess)
178:                 {
179:                     retryCount++;
180:                     continue;
181:                 }
182: 
183:                 // 2. 重新定位（偏差计算专用）并计算与目标像素点的差值
184:                 var(deltaX, deltaY) = CalculatePixelDeviation(prName, targetX, targetY);
185: 
186:                 (finalDeltaX, finalDeltaY) = (deltaX, deltaY);
187: 
188: 
189:                 // 3. 检查偏差是否在阈值内
190:                 if (Math.Abs(deltaX) < pixelTolerance && Math.Abs(deltaY) < pixelTolerance)
191:                 {
192:                     isWithinTolerance = true;
193:                     break;
194:                 }
195: 
196:                 retryCount++;
197:             }
198: 
199:             if (!isWithinTolerance)
200:             {
201:                 // var finalDeviation = CalculatePixelDeviation(prName, targetX, targetY);
202: 
203:                 DialogResult dialog = AKRSXtraMessageBox.Show($"超过最大重试次数（{ maxRetry}次），当前与目标像素点(1224, 1024)偏差：X方向{ finalDeltaX: F2}像素，Y方向{ finalDeltaY: F2}像素",
204:                     "Prompt",
205:                     MessageBoxButtons.OK,
206:                     MessageBoxIcon.Information);
207:             }
208: 
209:             return isWithinTolerance;
210:         }
211: 
212:         /// <summary>
213:         /// 单次定位并移动到相机中心
214:         /// </summary>
215:         /// <param name="prName">PR名称</param>
216:         /// <param name="camType">相机类型</param>
217:         /// <returns></returns>
218:         private MatchResult LocateAndMoveOnce(string prName, CamCoordinateType camType)
219:         {
220:             var matchResult = this.LocatePosition(prName);
221:             if (matchResult != null && matchResult.IsSuccess)
222:             {
223:                 this.MoveToCamCenter(camType, matchResult);
224:             }
225:             return matchResult;
226:         }
227: 
228:         /// <summary>
229:         /// 重新定位并计算与目标像素点的偏差（像素单位）
230:         /// </summary>
231:         /// <param name="prName">PR模板名称</param>
232:         /// <param name="targetX">目标X像素</param>
233:         /// <param name="targetY">目标Y像素</param>
234:         /// <returns>偏差值（像素）</returns>
235:         private (double deltaX, double deltaY) CalculatePixelDeviation(string prName, double targetX, double targetY)
236:         {
237:             // 重新定位获取最新位置（偏差计算专用）
238:             var latestResult = this.LocatePosition(prName);
239:             if (latestResult == null || !latestResult.IsSuccess)
240:             {
241:                 return (double.MaxValue, double.MaxValue); // 定位失败时返回最大偏差
242:             }
243: 
244:             // 计算当前位置与目标像素点的差值（像素单位）
245:             double deltaX = latestResult.CenterX - targetX;
246:             double deltaY = latestResult.CenterY - targetY;
247: 
248:             // 返回欧氏距离作为偏差（也可根据需求返回X/Y轴独立偏差）
249:             return (deltaX, deltaY);

318:         public MatchResult LocatePosition(string patternName)
319:         {
320:             // 获取Pr实体
321:             PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance().Find(patternName);
322: 
323:             Thread.Sleep(200);
324:             ExcuteResult excuteResult = pREntity.DoWork();
325: 
326:             // 拍照失败，直接返回错误
327:             if (excuteResult != ExcuteResult.Success)
328:             {
329:                 throw new ArgumentNullException(patternName, "The" + patternName + " excuteResult is fail.");
330:             }
331: 
332:             // 获取定位结果
333:             MatchResult matchResult = (MatchResult)pREntity.AlgResult;
334: 
335:             return matchResult;
336:         }

