308:                     BondDevicePara.GetInstance().BMCDevicePara.MeasureHeightResult = res.HeightValue;
309:                     BondDevicePara.GetInstance().Save();
310:                 }
311:                 else
312:                 {
313:                     AKRSXtraMessageBox.Show("测高失败");
314:                     return false;
315:                 }
316: 
317:                 // Bond Z 和 相机的Z轴偏移量
318:                 this.calibratePara.BondRotateCenterToCamOffset.Z =
319:                     -(this.calibratePara.BMCVisionMachinePos.Z - BondDevicePara.GetInstance().BMCDevicePara.MeasureHeightResult);
320: 
321:                 this.bondHeadController.CloseToolVaccum();
322: 
323:                 // Bond相机移动到BMC中心点上方
324:                 this.bondModuleController.MoveSafeBondXYZ(this.calibratePara.BMCVisionMachinePos);
325: 
326:                 // 定位BMC 中心点
327:                 MatchResult bigMatchResult = this.LocatePosition(this.calibratePara.BmcPRName);
328: 
329:                 // 移动到相机中心点
330:                 this.calibController.MoveToCamCenter(CalibController.CamCoordinateType.Bond, bigMatchResult);
331: 
332:                 this.calibController.LocateAndMoveToTargetPixel(this.calibratePara.BmcPRName, CalibController.CamCoordinateType.Bond, 1, 2);
333: 
334:                 this.calibratePara.BMCVisionMachinePos = this.bondModuleController.Get3DRealPosition();
335: 
336:                 // 创建BMC标定点位列表
337:                 this.bmcCalibPoints = CalibService.GeneratePointList(this.calibratePara.BMCVisionMachinePos, 0.1, 0.05, 6, 5);

123:             // 安全高度
124:             double safeHeight = this.GetBondheadSafeLevel(point3D);
125: 
126:             this.bondModule.CheckSoftLimit(point3D);
127: 
128:             // 单步工作
129:             if (!System2Domain.GetInstance().WaitSingleStep())
130:             {
131:                 return;
132:             }
133: 
134:             LogHelper.Post(
135:                 Level.Info,
136:                 $"系统2-轴准备移动，当前高度：{curLevel}，安全高度：{safeHeight}，目标位置：{point3D}",
137:                 LogCategory.Bond,
138:                 ViewType.InFileAndUI);
139: 
140:             if (curLevel >= safeHeight && point3D.Z >= safeHeight)
141:             {
142:                 // 当前位置高于安全高度且目标位置位置也高于安全高度,先移动XY，再移动Z轴
143:                 this.bondModule.MoveBondXY(point3D.X, point3D.Y);
144: 
145:                 this.bondHeadController.MoveZAxis(point3D.Z);
146:             }
147:             else if (curLevel >= safeHeight && point3D.Z < safeHeight)
148:             {
149:                 // 当前位置比安全位置高，目标位置比安全位置低，先移动XY，再移动Z轴
150:                 this.bondModule.MoveBondXY(point3D.X, point3D.Y);
151: 
152:                 this.bondHeadController.MoveZAxis(point3D.Z);
153:             }
154:             else if (curLevel < safeHeight && point3D.Z >= safeHeight)
155:             {
156:                 // 当前位置比安全位置低，目标位置比安全位置高，先移动Z轴，再移动XY，这个地方应该是连续运动
157:                 this.bondHeadController.MoveZAxis(point3D.Z);
158: 
159:                 this.bondModule.MoveBondXY(point3D.X, point3D.Y);
160:             }
161:             else if (curLevel < safeHeight && point3D.Z < safeHeight)
162:             {
163:                 // 如果当前位置和目标位置都比安全位置低，Z轴移动到安全位置，移动XY，最后移动Z轴
164:                 this.bondHeadController.MoveZAxis(safeHeight);
165:                 this.bondModule.MoveBondXY(point3D.X, point3D.Y);
166: 
167:                 this.bondHeadController.MoveZAxis(point3D.Z);
168:             }
169:             else
170:             {
171:                 // 理论上不会进到这个分支
172:                 AKRSXtraMessageBox.Show(
173:                     $"致命错误!设备将退出工作，请联系供应商处理!",
174:                     "Error",
175:                     MessageBoxButtons.OK,
176:                     MessageBoxIcon.Error);
177: 
178:                 throw new Exception("安全移动XYZ轴到指定位置出错!");

