1060:         private void PreliminaryCompensationX()
1061:         {
1062:             for (int k = 0; k < 2; k++)
1063:             {
1064:                 for (int i = 0; i < this.GlobalCalibrationDomain.RowCount; i++)
1065:                 {
1066:                     for (int j = 0; j < this.GlobalCalibrationDomain.ColumnCount; j++)
1067:                     {
1068:                         if (this.isStop)
1069:                         {
1070:                             return;
1071:                         }
1072: 
1073:                         if (i == 0)
1074:                         {
1075:                             AKRSPoint3D point3D = new AKRSPoint3D(
1076:                                 this.GlobalCalibrationDomain.StartPoint3D.X
1077:                                 + j * this.GlobalCalibrationDomain.ColumnSpacing,
1078:                                 this.GlobalCalibrationDomain.StartPoint3D.Y
1079:                                 + i * this.GlobalCalibrationDomain.RowSpacing,
1080:                                 this.GlobalCalibrationDomain.StartPoint3D.Z);
1081: 
1082:                             this.MoveXY(point3D.X, point3D.Y);
1083: 
1084:                             Thread.Sleep(this.GlobalCalibrationDomain.Delay);
1085: 
1086:                             // 寻找Pr模板
1087:                             PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance()
1088:                                 .Find(this.GlobalCalibrationDomain.PrName);
1089: 
1090:                             ExcuteResult re = pREntity.DoWork(this.bondModule.GetHardware(), false);
1091: 
1092:                             if (re == ExcuteResult.Success)
1093:                             {
1094:                                 MatchResult matchResult = (MatchResult)pREntity.AlgResult;
1095: 
1096:                                 double x = -(1224.0 - matchResult.CenterX) * (double)this.SpinX.Value * this.direct;
1097: 
1098:                                 double y = (1024.0 - matchResult.CenterY) * (double)this.SpinY.Value * this.direct;
1099: 
1100:                                 this.stageAxisXMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] += x;
1101: 
1102:                                 this.result.Add(
1103:                                     new List<double>()
1104:                                         {
1105:                                             matchResult.CenterX,
1106:                                             matchResult.CenterY,
1107:                                             point3D.X,
1108:                                             point3D.Y,
1109:                                             x,
1110:                                             y,
1111:                                             this.stageAxisXMapping[
1112:                                                 i * this.GlobalCalibrationDomain.ColumnCount + j],
1113:                                             this.stageAxisYMapping[
1114:                                                 i * this.GlobalCalibrationDomain.ColumnCount + j]
1115:                                         });
1116:                             }
1117:                             else
1118:                             {
1119:                                 throw new Exception("定位失败，请检查标定板是否有问题");
1120:                             }
1121:                         }
1122:                         else
1123:                         {
1124:                             this.stageAxisXMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] =
1125:                                 this.stageAxisXMapping[j];
1126:                         }
1127:                     }
1128:                 }
1129: 
1130:                 this.SaveData(k);
1131:             }

