602:                         Stopwatch stopwatch = new Stopwatch();
603: 
604:                         this.MoveXY(point3D.X, point3D.Y);
605: 
606:                         Thread.Sleep(this.GlobalCalibrationDomain.Delay);
607: 
608:                         // 寻找Pr模板
609:                         PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance()
610:                             .Find(this.GlobalCalibrationDomain.PrName);
611: 
612:                         ExcuteResult re = pREntity.DoWork(this.bondModule.GetHardware(), false);
613: 
614:                         if (re == ExcuteResult.Success)
