657:                             this.stageAxisXMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] += 0;
658:                             this.stageAxisYMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] += 0;
659:                         }
