581:         private void Mapping2DCalibration(int count)
582:         {
583:             this.bondModule.MoveBondXYZ(this.GlobalCalibrationDomain.StartPoint3D);
584: 
585:             for (int k = 0; k < count; k++)
586:             {
587:                 for (int i = 0; i < this.GlobalCalibrationDomain.RowCount; i++)
588:                 {
589:                     for (int j = 0; j < this.GlobalCalibrationDomain.ColumnCount; j++)
590:                     {
591:                         if (this.isStop)
592:                         {
593:                             return;
594:                         }
595: 
596:                         AKRSPoint3D point3D = new AKRSPoint3D(
597:                             this.GlobalCalibrationDomain.StartPoint3D.X
598:                             + j * this.GlobalCalibrationDomain.ColumnSpacing,
599:                             this.GlobalCalibrationDomain.StartPoint3D.Y + i * this.GlobalCalibrationDomain.RowSpacing,
600:                             this.GlobalCalibrationDomain.StartPoint3D.Z);
601: 
602:                         Stopwatch stopwatch = new Stopwatch();
603: 
604:                         this.MoveXY(point3D.X, point3D.Y);
605: 
606:                         Thread.Sleep(this.GlobalCalibrationDomain.Delay);
607: 
608:                         // 寻找Pr模板
609:                         PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance()
610:                             .Find(this.GlobalCalibrationDomain.PrName);
611: 
612:                         ExcuteResult re = pREntity.DoWork(this.bondModule.GetHardware(), false);
613: 
614:                         if (re == ExcuteResult.Success)
615:                         {
616:                             MatchResult matchResult = (MatchResult)pREntity.AlgResult;
617: 
618:                             double x = -(1224.0 - matchResult.CenterX) * (double)this.SpinX.Value * this.direct;
619: 
620:                             double y = (1024.0 - matchResult.CenterY) * (double)this.SpinY.Value * this.direct;
621: 
622:                             this.stageAxisXMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] += x;
623:                             this.stageAxisYMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] += y;
624: 
625:                             this.result.Add(
626:                                 new List<double>()
627:                                     {
628:                                         matchResult.CenterX,
629:                                         matchResult.CenterY,
630:                                         point3D.X,
631:                                         point3D.Y,
632:                                         x,
633:                                         y,
634:                                         this.stageAxisXMapping
635:                                             [i * this.GlobalCalibrationDomain.ColumnCount + j],
636:                                         this.stageAxisYMapping[
637:                                             i * this.GlobalCalibrationDomain.ColumnCount + j],
638:                                         this.bondModule.BondAxisX.GetRealPosition(),
639:                                         this.bondModule.BondAxisY.GetRealPosition()
640:                                     });
641:                         }
642:                         else
643:                         {
644:                             this.result.Add(
645:                                 new List<double>()
646:                                     {
647:                                         999,
648:                                         999,
649:                                         999,
650:                                         999,
651:                                         999,
652:                                         999,
653:                                         999,
654:                                         999
655:                                     });
656: 
657:                             this.stageAxisXMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] += 0;
658:                             this.stageAxisYMapping[i * this.GlobalCalibrationDomain.ColumnCount + j] += 0;
659:                         }
660:                     }
661:                 }
662: 
663:                 this.SaveData(k);
664:             }

