248:     private static async Task OnControlRunAsync(
249:         Control control,
250:         Delegate action,
251:         List<Control> controls = null,
252:         params object[] objects)
253:     {
254:         if (signal.CurrentCount == 0)
255:         {
256:             AKRSXtraMessageBox.Show("当前正在执行其他动作！", "后台任务执行提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
257:             return;
258:         }
259: 
260:         try
261:         {
262:             await signal.WaitAsync().ConfigureAwait(false);
263:             Control parent = control.Parent;
264:             controls?.ForEach(it => parent = FindNearestCommonParent(parent, it.Parent));
265:             parent?.SuspendLayout();
266: 
267:             ToggleControlsEnabled(control, controls, false);
268: 
269:             string actionInfo = $"{action?.Method.Name}--{action?.Method.DeclaringType?.FullName}";
270: 
271:             try
272:             {
273:                 await Task.Run(async () =>
274:                 {
275:                     await AsyncHelper.ExecuteAsync(action, ex => { HandleException(ex, actionInfo); }, objects)
276:                         .ConfigureAwait(false);
277:                 }).ConfigureAwait(false);
278:             }
279:             catch (Exception e)
280:             {
281:                 HandleException(e, actionInfo);
282:             }
283: 
284:             ToggleControlsEnabled(control, controls, true);
285: 
286:             parent?.ResumeLayout(false);
287:         }
288:         catch (Exception e)
289:         {
290:         }
291:         finally
292:         {
293:             signal.Release();
294:         }
295:     }
296: 
297:     private static void HandleException(Exception e, string actionInfo)
298:     {
299:         StringBuilder sb = new();
300:         sb.Append(e.Message);
301:         sb.Append("\t");
302:         sb = ConnectInnerExceptionMessage(sb, e);
303: 
304:         MainForm.SendUiAction(() =>
305:         {
306:             AKRSXtraMessageBox.Show(sb.ToString(), "后台任务执行异常提示", MessageBoxButtons.OK, MessageBoxIcon.Error);
307:         });
308:     }

18:     public static async Task ExecuteAsync(Delegate action, Action<Exception> exceptionHandler = null, params object[] parameters)
19:     {
20:         try
21:         {
22:             if (action is Func<Task> asyncFunc)
23:             {
24:                 await ((Task)asyncFunc.DynamicInvoke()).ConfigureAwait(false);
25:             }
26:             else if (action is Func<object[], Task> asyncFuncWithParams)
27:             {
28:                 await ((Task)asyncFuncWithParams.DynamicInvoke(parameters)).ConfigureAwait(false);
29:             }
30:             else
31:             {
32:                 await Task.Run(() => { action.DynamicInvoke(parameters); }).ConfigureAwait(false);
33:             }
34:         }
35:         catch (Exception e)
36:         {
37:             exceptionHandler?.Invoke(e);
38:         }

