504:     /// <summary>
505:     /// 计算并填充每个象限数据
506:     /// </summary>
507:     /// <param name="sourceList"></param>
508:     /// <param name="rowCount"></param>
509:     /// <param name="colCount"></param>
510:     private List<GlobalCalibrationData> CalcAndFillQuadrant(List<GlobalCalibrationData> sourceList, int rowCount,
511:         int colCount, double rowSpace, double colSpace)
512:     {
513:         if (rowCount == 0 || colCount == 0)
514:         {
515:             throw new ArgumentOutOfRangeException($"{nameof(colCount)} / {nameof(rowCount)}", "行/列数不能为0");
516:         }
517: 
518:         // 根据rowCount、colCount判断象限
519:         int quadrant = 0;
520:         if (rowCount > 0 && colCount > 0)
521:         {
522:             quadrant = 1;
523:         }
524:         else if (colCount < 0 && rowCount > 0)
525:         {
526:             quadrant = 2;
527:         }
528:         else if (colCount < 0 && rowCount < 0)
529:         {
530:             quadrant = 3;
531:         }
532:         else
533:         {
534:             quadrant = 4;
535:         }
536: 
537:         int colSign = quadrant is 1 or 4 ? 1 : -1;
538:         int rowSign = quadrant is 1 or 2 ? 1 : -1;
539:         List<GlobalCalibrationData> dataToAdd = new();
540:         for (int i = 0; i < Math.Abs(rowCount) + 1; i++)
541:         {
542:             for (int j = 0; j < Math.Abs(colCount) + 1; j++)
543:             {
544:                 double worldX = j * colSpace * colSign;
545:                 double worldY = i * rowSpace * rowSign;
546:                 if (sourceList.Exists(d => MathService.DoubleEqual(d.WorldX, worldX) && MathService.DoubleEqual(d.WorldY, worldY)))
547:                 {
548:                     continue;
549:                 }
550: 
551:                 dataToAdd.Add(new() { WorldX = worldX, WorldY = worldY });
552:             }
553:         }
554: 
555:         return dataToAdd;
556:     }
