659:     private Task ScanPoints(bool simRunFlag, CancellationToken ct)
660:     {
661:         if (simRunFlag)
662:         {
663:             return Task.Run(async () =>
664:             {
665:                 string fileName = $"D:\\2025二维标定数据采集\\新数据采集{DateTime.Now:HHmmss}";
666:                 IDataLog dataLog = DataLogManager.Instance.CreateDataLog($"二维标定新数据采集{DateTime.Now:HHmmss}")
667:                     .ConfigureFileOutput($"{fileName}.json");
668: 
669:                 await Task.Run(async () =>
670:                 {
671:                     int count = 0;
672: 
673:                     foreach (GlobalCalibrationData data in this.GlobalCalibrationDomain.ScanData)
674:                     {
675:                         this.pauseSignal.WaitOne();
676:                         if (this.cts.IsCancellationRequested)
