684:                         await Task.Delay(this.GlobalCalibrationDomain.Delay);
685: 
686:                         Random random = new();
687: 
688:                         // 计算Mark在轴坐标系中的位置
689:                         data.ScanAxisX = data.AxisX + random.NextDouble() * 0.004 - 0.002;
690:                         data.ScanAxisY = data.AxisY + random.NextDouble() * 0.004 - 0.002;
691: 
692:                         dataLog.AddData("轴指令位置", new { X = data.AxisX, Y = data.AxisY });
693:                         dataLog.AddData("Mark轴坐标", new { X = data.ScanAxisX, Y = data.ScanAxisY });
694:                         dataLog.CommitData();
695: 
696:                         if (count % 10 == 0)
697:                         {
698:                             await dataLog.FlushAsync();
699:                         }
700:                     }
701: 
702:                     this.GlobalCalibrationDomain.Save();
703:                 }, this.cts.Token).ConfigureAwait(false);
704:             }, ct);

708:             return Task.Run(async () =>
