710:                 string fileName = $"D:\\2025二维标定数据采集\\新数据采集{DateTime.Now:HHmmss}";
711:                 IDataLog dataLog = DataLogManager.Instance.CreateDataLog($"二维标定新数据采集{DateTime.Now:HHmmss}")
712:                     .ConfigureFileOutput($"{fileName}.json");
