48:         }
49: 
50:         this.compensationRows = calibrationData
51:             .GroupBy(d => Math.Round(d.WorldY, 6))
52:             .OrderBy(g => g.Key)
53:             .Select(g => g.OrderBy(d => d.WorldX)
54:                 .Select(d => new KeyValuePair<Coords2D, Coords2D>(
55:                     new(d.AxisX, d.AxisY),
