62:     private bool FindInterpolationCell(Coords2D pt, out KeyValuePair<Coords2D, Coords2D>[] cellCorners)
63:     {
64:         cellCorners = null;
65: 
66:         for (int i = 0; i < this.compensationRows.Count - 1; i++)
67:         {
68:             List<KeyValuePair<Coords2D, Coords2D>> rowA = this.compensationRows[i];
69:             List<KeyValuePair<Coords2D, Coords2D>> rowB = this.compensationRows[i + 1];
70: 
71:             int cols = Math.Min(rowA.Count, rowB.Count);
72: 
73:             for (int j = 0; j < cols - 1; j++)
74:             {
75:                 KeyValuePair<Coords2D, Coords2D> p11 = rowA[j];
76:                 KeyValuePair<Coords2D, Coords2D> p12 = rowA[j + 1];
77:                 KeyValuePair<Coords2D, Coords2D> p21 = rowB[j];
78:                 KeyValuePair<Coords2D, Coords2D> p22 = rowB[j + 1];
79: 
80:                 if (this.IsPointInQuad(pt, p11.Key, p21.Key, p22.Key, p12.Key))
81:                 {
82:                     cellCorners = new[] { p11, p21, p12, p22 };
83:                     return true;
84:                 }
85:             }
86:         }
87: 
88:         return false;
89:     }

