117:     /// <returns>补偿值</returns>
118:     /// <exception cref="InvalidOperationException">网格顶点异常</exception>
119:     private AKRSPoint2D BilinearInterpolation(Coords2D pt, KeyValuePair<Coords2D, Coords2D>[] corners)
120:     {
121:         KeyValuePair<Coords2D, Coords2D> q11 = corners[0];
122:         KeyValuePair<Coords2D, Coords2D> q21 = corners[1];
123:         KeyValuePair<Coords2D, Coords2D> q12 = corners[2];
124:         KeyValuePair<Coords2D, Coords2D> q22 = corners[3];
125: 
126:         double x1 = q11.Key.X, x2 = q22.Key.X;
127:         double y1 = q11.Key.Y, y2 = q22.Key.Y;
128: 
129:         double denom = (x2 - x1) * (y2 - y1);
130:         if (Math.Abs(denom) < 1e-10)
131:         {
132:             throw new InvalidOperationException("网格顶点异常");
133:         }
134: 
135:         double fxy1 = ((x2 - pt.X) * q11.Value.X + (pt.X - x1) * q21.Value.X) / (x2 - x1);
136:         double fxy2 = ((x2 - pt.X) * q12.Value.X + (pt.X - x1) * q22.Value.X) / (x2 - x1);
137:         double interpX = ((y2 - pt.Y) * fxy1 + (pt.Y - y1) * fxy2) / (y2 - y1);
138: 
139:         fxy1 = ((x2 - pt.X) * q11.Value.Y + (pt.X - x1) * q21.Value.Y) / (x2 - x1);
140:         fxy2 = ((x2 - pt.X) * q12.Value.Y + (pt.X - x1) * q22.Value.Y) / (x2 - x1);
141:         double interpY = ((y2 - pt.Y) * fxy1 + (pt.Y - y1) * fxy2) / (y2 - y1);
142: 
143:         return new(interpX, interpY);
144:     }
