151:     /// <param name="b">顶点2</param>
152:     /// <param name="c">顶点3</param>
153:     /// <param name="d">顶点4</param>
154:     /// <returns>判断结果</returns>
155:     private bool IsPointInQuad(Coords2D pt, Coords2D a, Coords2D b, Coords2D c, Coords2D d)
156:     {
157:         return this.SameSide(pt, a, b, c) && this.SameSide(pt, b, c, d) && this.SameSide(pt, c, d, a) &&
158:                this.SameSide(pt, d, a, b);
159:     }
