1677:     /// </summary>
1678:     /// <param name="tdMarkShotPos">温漂Mark拍摄位置</param>
1679:     /// <param name="tdMarkAxisPos">温漂Mark当前位置</param>
1680:     /// <param name="axisPos">目标轴位置</param>
1681:     /// <returns>补偿值</returns>
1682:     private AKRSPoint2D Predict(AKRSPoint2D tdMarkShotPos, AKRSPoint2D tdMarkAxisPos, AKRSPoint2D axisPos)
1683:     {
1684:         if (this.predictor == null)
1685:         {
1686:             return new(0, 0);
1687:         }
1688: 
1689:         PointF tdOffset = ((tdMarkAxisPos - tdMarkShotPos) * 1000).ToPointF();
1690:         PointF inputAxisPos = (axisPos * 1000).ToPointF();
1691:         float[] input = new float[] { tdOffset.X, tdOffset.Y, inputAxisPos.X, inputAxisPos.Y };
1692: 
1693:         float[] output = this.predictor.Predict(input);
1694:         return new(output[0], output[1]);

