863:         private void ScaleX()
864:         {
865:             this.CloseXOffset();
866: 
867:             bool isFirst = true;
868: 
869:             List<double> result = new List<double>();
870: 
871:             for (int i = 0; i < this.SpCycleTimes.Value; i++)
872:             {
873:                 for (int j = 0; j < this.GlobalCalibrationDomain.ColumnCount; j++)
874:                 {
875:                     if (this.isStop)
876:                     {
877:                         return;
878:                     }
879: 
880:                     AKRSPoint3D point3D = new AKRSPoint3D(
881:                         this.GlobalCalibrationDomain.StartPoint3D.X + j * this.GlobalCalibrationDomain.ColumnSpacing,
