1056:         public static int[,] SizeAutoExpend(int[,] compensate, int rowMax, int columnMax)
1057:         {
1058:             int[,] expendCompensate = new int[columnMax, rowMax];
1059: 
1060:             for (int i = 0; i < columnMax; i++)
1061:             {
1062:                 for (int j = 0; j < rowMax; j++)
1063:                 {
1064:                     if (j > compensate.GetLength(1) - 1 && i > compensate.GetLength(0) - 1)
1065:                     {
1066:                         expendCompensate[i, j] = compensate[compensate.GetLength(0) - 1, compensate.GetLength(1) - 1];
1067:                     }
1068:                     else if (j > compensate.GetLength(1) - 1)
1069:                     {
1070:                         // 如果列数大于原来的则用最后一个
1071:                         expendCompensate[i, j] = compensate[i, compensate.GetLength(1) - 1];
1072:                     }
1073:                     else if (i > compensate.GetLength(0) - 1)
1074:                     {
1075:                         // 如果列数大于原来的则用最后一个
1076:                         expendCompensate[i, j] = compensate[compensate.GetLength(0) - 1, j];
1077:                     }
1078:                     else
1079:                     {
1080:                         expendCompensate[i, j] = compensate[i, j];
1081:                     }
1082:                 }
1083:             }
1084: 
1085:             return expendCompensate;

